SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END opened_cohort, COUNT(CASE WHEN account_type = 'CREDIT' THEN 1 END) credit_count, SUM(CASE WHEN account_type = 'CREDIT' THEN balance ELSE 0 END) credit_balance FROM accounts GROUP BY CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING SUM(CASE WHEN status = 'CLOSED' THEN 1 ELSE 0 END) > 34 ORDER BY credit_count, credit_balance DESC
